using Mono.Cecil;using Mono.Cecil.Cil;using System.Security.Cryptography;using System.Text.Json;
const string Original="864b641f5458b8099980f7ced378e1df7023fe60b70195f8de6272dee3d790d0";
string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
string Shape(MethodDefinition m){if(!m.HasBody)return "none";var ins=m.Body.Instructions;string Op(object o)=>o switch{Instruction i=>"@"+ins.IndexOf(i),Instruction[] a=>string.Join(",",a.Select(i=>ins.IndexOf(i))),_=>o?.ToString()??""};return string.Join("\n",ins.Select(i=>i.OpCode.Name+":"+Op(i.Operand)))+"/"+string.Join(",",m.Body.Variables.Select(v=>v.VariableType.FullName))+"/"+string.Join(",",m.Body.ExceptionHandlers.Select(e=>$"{e.HandlerType}:{e.CatchType}:{ins.IndexOf(e.TryStart)}:{ins.IndexOf(e.TryEnd)}:{ins.IndexOf(e.HandlerStart)}:{ins.IndexOf(e.HandlerEnd)}"));}
string Metadata(AssemblyDefinition a)=>a.Name.FullName+"\n"+string.Join("\n",a.MainModule.AssemblyReferences.Select(x=>x.FullName))+"\n"+string.Join("\n",a.MainModule.Types.SelectMany(All).SelectMany(t=>new[]{t.FullName+":"+t.Attributes}.Concat(t.Fields.Select(f=>f.FullName+":"+f.Attributes)).Concat(t.Methods.Select(m=>m.FullName+":"+m.Attributes+":"+m.ImplAttributes)).Concat(t.CustomAttributes.Select(x=>x.AttributeType.FullName+":"+string.Join(",",x.ConstructorArguments.Select(c=>c.Value))))))+"\n"+string.Join("\n",a.MainModule.Resources.Select(r=>r.Name+":"+(r is EmbeddedResource er?Convert.ToHexString(SHA256.HashData(er.GetResourceData())):r.ResourceType.ToString())));
void Guard(string output,string input){var full=Path.GetFullPath(output);if(full.Equals(Path.GetFullPath(input),StringComparison.OrdinalIgnoreCase)||File.Exists(full)||Directory.Exists(full)||File.Exists(full+".receipt.json"))throw new InvalidOperationException("New distinct output required");for(var d=new DirectoryInfo(Path.GetDirectoryName(full)!);d!=null;d=d.Parent){if(new[]{"BepInEx","UserData","mods","abdata"}.Contains(d.Name,StringComparer.OrdinalIgnoreCase)||d.Name.EndsWith("_Data",StringComparison.OrdinalIgnoreCase)||File.Exists(Path.Combine(d.FullName,".git"))||Directory.Exists(Path.Combine(d.FullName,".git")))throw new InvalidOperationException("Runtime/content/repository output denied");if(File.Exists(Path.Combine(d.FullName,"CharaStudio.exe"))&&Path.GetRelativePath(d.FullName,full).Split(Path.DirectorySeparatorChar)[0]!=".scratch")throw new InvalidOperationException("Only private scratch output below game allowed");}}
void Write(AssemblyDefinition a,string output){using var memory=new MemoryStream();a.Write(memory);Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);using var stream=new FileStream(output,FileMode.CreateNew);memory.Position=0;memory.CopyTo(stream);}
if(args.Length!=4||args[0]!="patch"&&args[0]!="probe")throw new ArgumentException("patch original game-root output | probe reviewed-input fixture output");var mode=args[0];var input=args[1];var aux=args[2];var output=args[3];Guard(output,input);string hash=Hash(input);if(mode=="patch"&&hash!=Original)throw new InvalidOperationException("Unsupported exact input");using var resolver=new DefaultAssemblyResolver();if(mode=="patch")foreach(var p in new[]{Path.Combine(aux,"BepInEx/core"),Path.Combine(aux,"BepInEx/plugins"),Path.Combine(aux,"CharaStudio_Data/Managed")}.Concat(Directory.GetDirectories(Path.Combine(aux,"BepInEx/plugins"),"*",SearchOption.AllDirectories)))resolver.AddSearchDirectory(p);
using var a=AssemblyDefinition.ReadAssembly(input,new ReaderParameters{AssemblyResolver=resolver});var module=a.MainModule;var m=module.GetType("PostProcessingEffectsV3.PostProcessingEffectsV3").Methods.Single(x=>x.Name=="ObjectsSelected");
if(mode=="probe"){if(hash!=Original){using var receipt=JsonDocument.Parse(File.ReadAllText(input+".receipt.json"));if(receipt.RootElement.GetProperty("originalSha256").GetString()!=Original||receipt.RootElement.GetProperty("candidateSha256").GetString()!=hash)throw new InvalidOperationException("Unreviewed input");}using var fixture=AssemblyDefinition.ReadAssembly(aux);Clone.Body(m,fixture.MainModule.GetType(m.DeclaringType.FullName).Methods.Single(x=>x.Name==m.Name),fixture.MainModule);Write(fixture,output);Console.WriteLine("Actual ObjectsSelected CIL extracted; game collaborators synthetic");return;}
var methods=module.Types.SelectMany(All).SelectMany(t=>t.Methods).ToArray();var before=methods.ToDictionary(x=>x.FullName,Shape);string meta=Metadata(a);var call=m.Body.Instructions.Single(i=>i.Operand is GenericInstanceMethod gm&&gm.Name=="First");var getter=(MethodReference)call.Previous.Operand;if(getter.Name!="get_SelectedObjects"||m.Body.ExceptionHandlers.Any(e=>m.Body.Instructions.IndexOf(call)>=m.Body.Instructions.IndexOf(e.TryStart)))throw new InvalidOperationException("Expected selection First before original catch");
var count=new MethodReference("get_Count",module.TypeSystem.Int32,getter.ReturnType){HasThis=true};var il=m.Body.GetILProcessor();foreach(var i in new[]{il.Create(OpCodes.Dup),il.Create(OpCodes.Callvirt,count),il.Create(OpCodes.Brtrue,call),il.Create(OpCodes.Pop),il.Create(OpCodes.Ret)})il.InsertBefore(call,i);foreach(var i in m.Body.Instructions)i.OpCode=i.OpCode.Code switch{Code.Bne_Un_S=>OpCodes.Bne_Un,Code.Leave_S=>OpCodes.Leave,_=>i.OpCode};m.Body.MaxStackSize=Math.Max(m.Body.MaxStackSize,2);
var changed=methods.Where(x=>before[x.FullName]!=Shape(x)).ToArray();if(changed.Length!=1||changed[0]!=m)throw new InvalidOperationException("Unexpected change closure");Write(a,output);using(var re=AssemblyDefinition.ReadAssembly(output,new ReaderParameters{AssemblyResolver=resolver})){if(Metadata(re)!=meta)throw new InvalidOperationException("Metadata changed");var after=re.MainModule.Types.SelectMany(All).SelectMany(t=>t.Methods).ToDictionary(x=>x.FullName,Shape);if(after.Count!=before.Count||before.Where(p=>p.Key!=m.FullName).Any(p=>after[p.Key]!=p.Value))throw new InvalidOperationException("Unrelated methods changed");}
var result=new{originalSha256=Original,candidateSha256=Hash(output),totalMethods=methods.Length,changedMethod=m.FullName,unchangedMethods=methods.Length-1,metadataUnchanged=true,newAssemblyReferences=0,installed=false};File.WriteAllText(output+".receipt.json",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));
